12	var castagnoliTable = crc32.MakeTable(crc32.Castagnoli)
13	
14	// CRC32 calculates the CRC32 checksum of the file at the given path.
15	func CRC32(path string) (uint32, error) {
16		f, err := os.Open(path)
17		if err != nil {
18			return 0, err
19		}
20		defer f.Close()
21	
22		h := crc32.New(castagnoliTable)
23		if _, err := io.Copy(h, f); err != nil {
24			return 0, err
25		}
26		return h.Sum32(), nil
27	}
28	
29	// CRC32WithTiming calculates the CRC32 checksum of the file at the given path
30	// and also returns the duration taken to compute it.
31	func CRC32WithTiming(path string) (uint32, time.Duration, error) {
32		startT := time.Now()
33		sum, err := CRC32(path)
34		if err != nil {
35			return 0, 0, err
36		}
37		return sum, time.Since(startT), nil
38	}
39	
40	// CRC32Writer wraps an io.Writer, computing a running CRC32 (Castagnoli)
41	// checksum over all data written through it.
42	type CRC32Writer struct {
43		h  hash.Hash32
44		mw io.Writer
45	}
46	
47	// NewCRC32Writer creates a new CRC32Writer that writes data to w while
48	// computing a running CRC32 checksum.
49	func NewCRC32Writer(w io.Writer) *CRC32Writer {
50		h := crc32.New(castagnoliTable)
51		return &CRC32Writer{
52			h:  h,
53			mw: io.MultiWriter(w, h),
54		}
55	}
56	
57	// Write writes p to the underlying writer and updates the CRC32 checksum.
58	func (c *CRC32Writer) Write(p []byte) (int, error) {
59		return c.mw.Write(p)
60	}
61	
62	// Sum32 returns the CRC32 checksum of all data written so far.
63	func (c *CRC32Writer) Sum32() uint32 {
64		return c.h.Sum32()
65	}
66	
67	// WriteCRC32SumFile writes the given CRC32 checksum to path as an 8-character
68	// lowercase hex string (e.g. "1a2b3c4d").
69	func WriteCRC32SumFile(path string, sum uint32) error {
70		return os.WriteFile(path, []byte(fmt.Sprintf("%08x", sum)), 0644)
71	}
72	
73	// ReadCRC32SumFile reads a CRC32 checksum previously written by WriteCRC32SumFile.
74	func ReadCRC32SumFile(path string) (uint32, error) {
75		b, err := os.ReadFile(path)
76		if err != nil {
77			return 0, err
78		}
79		var sum uint32
80		if _, err := fmt.Sscanf(string(b), "%08x", &sum); err != nil {
81			return 0, fmt.Errorf("invalid checksum file: %w", err)
82		}
83		return sum, nil
84	}
