		for _, srcPath := range walMatches {
			name := filepath.Base(srcPath)

			// Verify each WAL file against its companion checksum file.
			crcPath := srcPath + crcSuffix
			match, err := rsum.CompareCRC32SumFile(srcPath, crcPath)
			if err != nil {
				return fmt.Errorf("verifying checksum for WAL file %s: %w", name, err)
			}
			if !match {
				return fmt.Errorf("checksum mismatch for WAL file %s", name)
			}

			dstPath := filepath.Join(s.snapTmpDirPath, name)
			if err := os.Rename(srcPath, dstPath); err != nil {
				return err
			}
			if !db.IsValidSQLiteWALFile(dstPath) {
				return fmt.Errorf("%s is not a valid SQLite WAL file", name)
			}
		}

		if err := os.Remove(movedDir); err != nil {
			return err
		}
	} else {
		if err := s.sinkW.Close(); err != nil {
			return err
		}
	}

	if err := writeMeta(s.snapTmpDirPath, s.meta); err != nil {
		return err
	}

	if err := os.Rename(s.snapTmpDirPath, s.snapDirPath); err != nil {
		return err
	}

